using SeedApi;

var client = new SeedApiClient();
await client.SubmitFormDataAsync(
    new PostSubmitRequest
    {
        Username = "johndoe",
        Email = "john@example.com",
        Content = "{\"key\":\"value\"}",
    }
);

using SeedApi;

var client = new SeedApiClient();
await client.GetTokenAsync(
    new TokenRequest { ClientId = "client_id", ClientSecret = "client_secret" }
);
